package net.officefloor.hq.app.claim;

import java.util.List;

/** amount is shown with two decimals; status is DRAFT, OPEN, PENDING, SETTLED or VOID; number is "" when none;
 *  due is the due fixed when the claim was settled, else (unless PENDING) the figure its person's last statement bound
 *  it to, "" while it is live (or bound to n/a); openedBy is "" when never opened; stated is whether
 *  the last statement bound it; corrects is the number a correction corrects, "" for any other claim;
 *  roundingDate is the date its rounding goes by (a correction's: the date of the claim it corrects);
 *  dueBy is the due-by fixed when the claim was created. */
public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String corrects,
        String roundingDate, String dueBy) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundingDate().toString(), claim.getDueBy().toString());
    }

    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
    public static java.math.BigDecimal fixedDue(Claim claim) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        return claim.isBound() ? claim.getStatedDue() : null;
    }

    public static List<ClaimResponse> from(List<Claim> claims) {
        return claims.stream().map(ClaimResponse::from).toList();
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.plugin.variable.Val;

public class AuditClaimStatus {
    public void audit(@Val ValidClaimStatus request, @Val Claim claim, @Val ClaimNumber number, People people, Audit audit, @Val RollupFigures before, Rollup rollup) {
        String event = switch (request.decision()) {
            case APPROVE -> "CLAIM_APPROVED";
            case REJECT -> "CLAIM_REJECTED";
            case NONE -> switch (claim.getStatus()) {
                case OPEN -> "CLAIM_OPENED";
                case PENDING -> "CLAIM_PENDING";
                case SETTLED -> "CLAIM_SETTLED";
                case VOID -> "CLAIM_VOIDED";
                case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
            };
        };
        String line = ClaimAudit.line(event, request.user(),
                people.find(claim.getSheetId(), claim.getPersonId()), claim, number.value());
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (request.decision() == ValidClaimStatus.Decision.REJECT) {
            line += " reason=" + request.reason();
        }
        audit.recordOnCommit(line);
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class ApplyClaimStatus {
    public void apply(@Val ValidClaimStatus request, @Val Claim claim, Sheets sheets, People people,
            Rates rates, Periods periods, Settings settings, ClaimNumbering numbering, Out<ClaimNumber> number)
            throws ClaimStatusRefusedException {
        RoundingMode rounding = Rounding.of(claim, settings.policyDate(claim.getSheetId()));
        if (periods.isClosed(claim.getSheetId(), claim.getDate())) {
            throw new ClaimStatusRefusedException("No claim dated inside a closed period can change status");
        }
        boolean steward = Settings.STEWARD.equals(settings.role(claim.getSheetId(), request.user()));
        if (request.decision() != ValidClaimStatus.Decision.NONE) {
            // Only a steward approves or rejects, and only a PENDING claim.
            if (claim.getStatus() != ClaimStatus.PENDING) {
                throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
            }
            if (!steward) {
                throw new ClaimStatusRefusedException("Only a steward can approve or reject a PENDING claim");
            }
        } else if (!claim.getStatus().canBecome(request.target())) {
            throw new ClaimStatusRefusedException(claim.getStatus(), request.target());
        }
        if (request.target() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
                && claim.getOpenedBy().equals(request.user())) {
            // Four eyes: the user who opened a claim cannot settle (or approve) it.
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
        }
        ClaimStatus target = request.target();
        if (target == ClaimStatus.SETTLED && request.decision() == ValidClaimStatus.Decision.NONE && !steward) {
            // A clerk settles only within the sheet's clerk limit, judged on the claim's due as shown;
            // a due of n/a is within any limit.
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal fixed = ClaimResponse.fixedDue(claim);
            BigDecimal figure = fixed != null || claim.isBound() ? fixed
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId()), rounding);
            BigDecimal due = LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId()),
                    sheets.today(claim.getSheetId()), rounding);
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                // Above the clerk limit the claim awaits a steward's approval.
                target = ClaimStatus.PENDING;
            }
        }
        if (target == ClaimStatus.OPEN && request.decision() == ValidClaimStatus.Decision.NONE) {
            claim.setNumber(numbering.next(claim.getSheetId(), claim.getDate()));
            claim.setOpenedBy(request.user());
        }
        // A voided claim keeps its number; numbers are never reused.
        number.set(new ClaimNumber(claim.getNumber()));
        if (target == ClaimStatus.SETTLED) {
            // Settling (or approving) fixes the due: the figure a statement bound it to (never while PENDING), else its amount (raised to the floor)
            // at the rate in force on the claim's date, with its late charge as of today frozen in; with no
            // figure it stays live (n/a until a rate is set).
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            BigDecimal figure = claim.isBound() && claim.getStatedDue() != null ? claim.getStatedDue()
                    : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), grade, claim.getDate()),
                    settings.floor(claim.getSheetId()), rounding);
            claim.setSettledDue(LateCharge.withCharge(claim, figure, settings.latePct(claim.getSheetId()),
                    sheets.today(claim.getSheetId()), rounding));
        }
        // A rejected claim is OPEN again, so bound again by the last statement if it included it.
        claim.setStatus(target);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class SaveClaimCreated {
    public void save(@Val ValidClaim request, @Val Person person, Claims claims, Sheets sheets, Audit audit, @Val RollupFigures before, Rollup rollup, Periods periods,
            net.officefloor.hq.app.setting.Settings settings,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        String sheetId = person.getSheetId();
        LocalDate date = request.date() != null ? request.date() : sheets.today(sheetId);
        if (periods.isClosed(sheetId, date)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        if (!person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, sheetId, person.getId(), claims);
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, request.note(), request.corrects(),
                date.plusDays(settings.termsFor(sheetId, person.gradeOn(date))));
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the named person (name
 * compared as the person form compares it), first adding the person with grade A when no one on
 * the sheet has that name. One change: a refused claim leaves no new person behind.
 */
public class SaveQuickClaim {

    private static final String GRADE = "A";

    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
            net.officefloor.hq.app.setting.Settings settings,
            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
        LocalDate date = sheets.today(sheetId);
        // Refuse before anything is written.
        if (periods.isClosed(sheetId, date)) {
            throw new InvalidClaimException("No claim can be added inside a closed period");
        }
        Person person = people.findByName(sheetId, request.name());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        RollupFigures beforeClaim = before;
        if (person == null) {
            person = people.add(sheetId, request.name(), GRADE);
            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
                    + " name=" + person.getName() + " grade=" + person.getGrade());
            rollup.recordChanges(sheetId, request.user(), before);
            beforeClaim = rollup.figures(sheetId);
        }
        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "",
                date.plusDays(settings.termsFor(sheetId, person.gradeOn(date))));
        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
        rollup.recordChanges(sheetId, request.user(), beforeClaim);
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}
